CREATE INDEX index_product_id ON products (product_id);
CREATE INDEX index_category_id ON categories (category_id);

select * from categories;
select product_id, name, description, brand, color, guarantee_period, image, modified_date, price, SIZE, weight, category_id from products 
order by price asc;
select * from specifications;
select * from inventories;

select brand from products 
order by price asc;

delete from specifications;
delete from products;